import{f as t,o as l,c as a,a2 as d}from"./chunks/framework.n5RLHRfo.js";const f=JSON.parse('{"title":"Text Field","description":"","frontmatter":{"title":"Text Field","order":1},"headers":[],"relativePath":"en/extended-objects/text-field/index.md","filePath":"en/extended-objects/text-field/index.md","lastUpdated":1792987289000}'),o={name:"en/extended-objects/text-field/index.md"};function i(r,e,n,s,c,x){return l(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="text-field" tabindex="-1">Text Field <a class="header-anchor" href="#text-field" aria-label="Permalink to &quot;Text Field&quot;">​</a></h1><p>RedGPU provides a <strong>TextField</strong> system that allows you to conveniently render text in 3D space. It internally utilizes HTML/SVG technology to output complex font styles and effects based on GPU acceleration.</p><h2 id="_1-key-features" tabindex="-1">1. Key Features <a class="header-anchor" href="#_1-key-features" aria-label="Permalink to &quot;1. Key Features&quot;">​</a></h2><ul><li><strong>HTML/SVG Based</strong>: You can use familiar CSS styles (font, color, alignment, etc.) directly.</li><li><strong>Spatial Placement</strong>: Supports <strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/TextField3D.html"><code>TextField3D</code></a></strong>, which is placed at actual coordinates within the 3D world.</li><li><strong>Automatic Sizing</strong>: The object&#39;s size is automatically updated according to the text content and style.</li><li><strong>Billboard Support</strong>: Can be set so that text always faces the camera.</li></ul><h2 id="_2-key-style-properties" tabindex="-1">2. Key Style Properties <a class="header-anchor" href="#_2-key-style-properties" aria-label="Permalink to &quot;2. Key Style Properties&quot;">​</a></h2><p>Text field objects provide the following style properties.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Property</th><th style="text-align:left;">Description</th><th style="text-align:left;">Default Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>text</code></td><td style="text-align:left;">String to display (supports <code>&lt;br/&gt;</code>)</td><td style="text-align:left;"><code>&quot;&quot;</code></td></tr><tr><td style="text-align:left;"><code>fontSize</code></td><td style="text-align:left;">Font size (px)</td><td style="text-align:left;"><code>24</code></td></tr><tr><td style="text-align:left;"><code>fontFamily</code></td><td style="text-align:left;">Font family</td><td style="text-align:left;"><code>&quot;Arial&quot;</code></td></tr><tr><td style="text-align:left;"><code>color</code></td><td style="text-align:left;">Text color (Hex, RGB, etc.)</td><td style="text-align:left;"><code>&quot;#fff&quot;</code></td></tr><tr><td style="text-align:left;"><code>background</code></td><td style="text-align:left;">Background color and transparency</td><td style="text-align:left;"><code>&quot;transparent&quot;</code></td></tr><tr><td style="text-align:left;"><code>textAlign</code></td><td style="text-align:left;">Text alignment (<code>left</code>, <code>center</code>, <code>right</code>)</td><td style="text-align:left;"><code>&quot;center&quot;</code></td></tr><tr><td style="text-align:left;"><code>padding</code></td><td style="text-align:left;">Padding (px)</td><td style="text-align:left;"><code>0</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">[HTML Tag Support]</p><p>You can handle line breaks using the <code>&lt;br/&gt;</code> tag in the <code>text</code> property.</p></div><h2 id="next-learning-roadmap" tabindex="-1">Next Learning Roadmap <a class="header-anchor" href="#next-learning-roadmap" aria-label="Permalink to &quot;Next Learning Roadmap&quot;">​</a></h2><ol><li><strong><a href="./textfield3d.html">TextField3D</a></strong>: Placing and controlling text in the 3D world</li><li><strong><a href="./../../interaction/">Interaction</a></strong>: Learning interaction via mouse and touch</li></ol><hr><h2 id="related-examples" tabindex="-1">Related Examples <a class="header-anchor" href="#related-examples" aria-label="Permalink to &quot;Related Examples&quot;">​</a></h2><ul><li><a href="/RedGPU/examples/3d/textField/textField3D/" target="_blank" rel="noopener noreferrer">TextField3D Basics</a></li><li><a href="/RedGPU/examples/3d/textField/textField3DCompare/" target="_blank" rel="noopener noreferrer">TextField3D Sizing Mode Comparison</a></li><li><a href="/RedGPU/examples/2d/textField2D/basic/" target="_blank" rel="noopener noreferrer">TextField2D Basics</a></li></ul><hr><p><a href="./textfield3d.html">Next Step: Learn TextField3D</a></p>',15)])])}const g=t(o,[["render",i]]);export{f as __pageData,g as default};
